  @names Map.keys(@paths)

  @doc "A built-in icon. Inherits `currentColor`; size it with CSS (defaults to 1em)."
  attr :name, :string, required: true, values: @names
  attr :class, :any, default: nil
  attr :rest, :global

  def icon(assigns) do
    assigns = assign(assigns, :d, Map.fetch!(@paths, assigns.name))

    ~H"""
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 256 256"
      fill="currentColor"
      aria-hidden="true"
      class={[@class, "sl-icon"]}
      {@rest}
    >
      <path d={@d} />
    </svg>
    """
  end

  @doc false
  def path(name), do: Map.fetch!(@paths, name)

  @doc false
  def names, do: @names

  @doc """
  Builds an `icon/1` component for your app from one or more icon sets.

      use SlopUI.Icons,
        sets: [
          phosphor: [weight: :regular, icons: ~w(house users bell)],
          hero: [icons: ~w(arrow-path)],
          app: [dir: "assets/icons", icons: :all]
        ]

  See `SlopUI.Icons.Set` for the presets and options.
  """
  defmacro __using__(opts) do
    quote do
      use Phoenix.Component

      require SlopUI.Icons.Set
      SlopUI.Icons.Set.define(unquote(opts))
    end
  end
end
